// ============================================
// Configuratie — pas deze waarden aan!
// ============================================
const ODOO_URL = 'https://jouw-odoo-url.com';
const ODOO_DB = 'jouw-database';
const ODOO_USER = 'admin';
const ODOO_PASSWORD = 'jouw-api-key';

// NAS configuratie
const NAS_BASE_PATH = '/share/Projecten';

const input = $input.first().json;
const projectId = parseInt(input.body?.project_id || input.project_id) || null;
const projectNaam = input.body?.project_naam || input.project_naam || '';

if (!projectId) {
  throw new Error('Geen project_id opgegeven.');
}

return [{
  json: {
    config: { url: ODOO_URL, db: ODOO_DB, user: ODOO_USER, password: ODOO_PASSWORD },
    projectId,
    projectNaam,
    nasBasePath: NAS_BASE_PATH,
    rpc: {
      jsonrpc: '2.0',
      id: 1,
      method: 'call',
      params: {
        service: 'common',
        method: 'authenticate',
        args: [ODOO_DB, ODOO_USER, ODOO_PASSWORD, {}]
      }
    }
  }
}];

// Bouw request om alle taken van het project op te halen
const authResponse = $input.first().json;
const uid = authResponse.result;
if (!uid) throw new Error('Odoo authenticatie mislukt!');

const setup = $('Setup').first().json;
const { config, projectId } = setup;

return [{
  json: {
    config, uid, projectId,
    rpc: {
      jsonrpc: '2.0',
      id: 2,
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          config.db, uid, config.password,
          'project.task', 'search_read',
          [[['project_id', '=', projectId]]],
          { fields: ['name', 'stage_id', 'parent_id', 'description'] }
        ]
      }
    }
  }
}];

// Bouw de geneste structuur en genereer verwachte NAS mappen
const tasksResponse = $input.first().json;
const tasks = tasksResponse.result || [];

const setup = $('Setup').first().json;
const { projectId, projectNaam, nasBasePath } = setup;

// Helpers
const getStage = (t) => Array.isArray(t.stage_id) ? t.stage_id[1] : '';
const getParentId = (t) => {
  if (Array.isArray(t.parent_id)) return t.parent_id[0];
  if (typeof t.parent_id === 'number') return t.parent_id;
  return null;
};
const safe = (str) => String(str).replace(/[^a-zA-Z0-9._-]/g, '_');

// Categoriseer taken
const blokken = tasks.filter(t => getStage(t) === 'Blokken');
const verdiepen = tasks.filter(t => getStage(t) === 'Verdiepen');
const collectoren = tasks.filter(t => getStage(t) === 'Collectoren');

// Helper: parse nummer uit description
const parseDesc = (desc) => {
  if (!desc) return {};
  try {
    const clean = desc.replace(/<[^>]*>/g, '').trim();
    const parsed = JSON.parse(clean);
    if (parsed._td) return parsed;
  } catch (e) {}
  return {};
};

// Bouw lijst van verwachte mappaden op de NAS
// Pad structuur: {basePath}/{projectNaam}/{gebouwNaam}/{verdiepNr}/Collector_{nr}
const projectPath = `${nasBasePath}/${safe(projectNaam)}`;
const verwachtePaden = new Set();
verwachtePaden.add(projectPath);

for (const gebouw of blokken) {
  const gebouwPath = `${projectPath}/${safe(gebouw.name)}`;
  verwachtePaden.add(gebouwPath);

  const gebouwVerdiepen = verdiepen.filter(v => getParentId(v) === gebouw.id);
  for (const verdiep of gebouwVerdiepen) {
    const numMatch = (verdiep.name || '').match(/Verdieping\s*([+-]?\d+)/);
    const verdiepNr = numMatch ? numMatch[1] : '0';
    const verdiepPath = `${gebouwPath}/${safe(verdiepNr)}`;
    verwachtePaden.add(verdiepPath);

    const verdiepCollectoren = collectoren.filter(c => getParentId(c) === verdiep.id);
    for (const collector of verdiepCollectoren) {
      const extra = parseDesc(collector.description);
      const colNumMatch = (collector.name || '').match(/Collector\s*(\d+)/);
      const colNr = extra.nummer || (colNumMatch ? colNumMatch[1] : '1');
      const collectorPath = `${verdiepPath}/Collector_${safe(String(colNr))}`;
      verwachtePaden.add(collectorPath);
    }
  }
}

return [{
  json: {
    projectPath,
    verwachtePaden: [...verwachtePaden],
    aantalVerwacht: verwachtePaden.size
  }
}];

// Genereer een eenvoudig cleanup command
// Strategie: schrijf verwachte paden naar een temp bestand,
// dan find + grep om overtollige mappen te vinden en verwijderen
const data = $input.first().json;
const { projectPath, verwachtePaden } = data;

// Bouw een reeks rm -rf commands voor mappen die NIET verwacht zijn
// We doen dit slim: genereer een script dat:
// 1. Alle bestaande mappen oplijst
// 2. Per map checkt of die in de verwachte lijst zit
// 3. Zo niet: verwijdert (diepste eerst)
const verwachteSetStr = verwachtePaden.join('\n');

const script = [
  // Controleer of projectmap bestaat
  `if [ ! -d '${projectPath}' ]; then echo 'GEEN_MAP'; exit 0; fi`,
  // Schrijf verwachte paden naar temp bestand
  `TMPFILE=$(mktemp)`,
  `cat > "$TMPFILE" << 'VERWACHT_EOF'`,
  verwachteSetStr,
  `VERWACHT_EOF`,
  // Vind en verwijder overtollige mappen (diepste eerst)
  `DELETED=""`,
  `for dir in $(find '${projectPath}' -mindepth 1 -type d | sort -r); do`,
  `  if ! grep -qxF "$dir" "$TMPFILE"; then`,
  `    rm -rf "$dir"`,
  `    DELETED="$DELETED$dir\n"`,
  `  fi`,
  `done`,
  `rm -f "$TMPFILE"`,
  // Output verwijderde mappen (of 'GEEN' als er niks verwijderd is)
  `if [ -z "$DELETED" ]; then echo 'GEEN'; else echo -e "$DELETED"; fi`
].join('\n');

return [{
  json: {
    projectPath,
    verwachtePaden,
    command: script
  }
}];

// Verwerk het resultaat van de cleanup
const sshResult = $input.first().json;
const stdout = (sshResult.stdout || sshResult.result || '').trim();

const buildData = $('Build Verwachte Paden').first().json;

let deleted = [];
let message = '';

if (stdout === 'GEEN_MAP') {
  message = 'Projectmap bestaat nog niet op NAS';
} else if (stdout === 'GEEN') {
  message = 'Geen overtollige mappen gevonden';
} else {
  deleted = stdout.split('\n').filter(line => line.trim().length > 0);
  message = `${deleted.length} overtollige map(pen) verwijderd`;
}

return [{
  json: {
    success: true,
    action: 'cleanup',
    verwachteMappen: buildData.aantalVerwacht,
    verwijderdeMappen: deleted.length,
    verwijderd: deleted,
    message
  }
}];
